insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field) values
('area:les-3-vallees','meta','line',0,'Les 3 Vallées | Linked ski areas | Snow Catchers','{}'::text[],'live','pilot import','title'),
('area:les-3-vallees','meta','line',1,'How Les 3 Vallées fits together, which base reaches which valley, how its snow changes with height, when the full pass pays, and what the area is like for boarders, families, food and evenings.','{}'::text[],'live','pilot import','description'),
('area:les-3-vallees','meta','line',2,'France','{}'::text[],'live','pilot import','crumbs.0.label'),
('area:les-3-vallees','meta','line',3,'Linked ski areas','{}'::text[],'live','pilot import','crumbs.1.label'),
('area:les-3-vallees','meta','line',4,'Northern Alps','{}'::text[],'live','pilot import','crumbs.2.label'),
('area:les-3-vallees','hero','lead',0,'Three valleys of the Tarentaise share one lift system, from the spa town of Brides-les-Bains at the bottom to the summit above Orelle at {{f:F000020}}. In a single day a skier can start in Courchevel, stop for lunch above Méribel and finish the afternoon in Val Thorens, the highest village in the area. The operator counts {{f:F000001}} of piste and puts its lowest runs at {{f:F000018}}.',array['F000001','F000018','F000020']::text[],'live','pilot import','hero.lead'),
('area:les-3-vallees','stats','line',0,'{{f:F000001}}',array['F000001']::text[],'live','pilot import','stats.0.v'),
('area:les-3-vallees','stats','line',1,'of linked piste on the operator''s count, the same figure skiresort.com gives','{}'::text[],'live','pilot import','stats.0.t'),
('area:les-3-vallees','stats','line',2,'{{f:F000023}} valleys',array['F000023']::text[],'live','pilot import','stats.1.v'),
('area:les-3-vallees','stats','line',3,'Saint-Bon, Les Allues and Les Belleville, with Orelle reached from the Maurienne','{}'::text[],'live','pilot import','stats.1.t'),
('area:les-3-vallees','stats','line',4,'{{f:F000018|n}} to {{f:F000020}}',array['F000018','F000020']::text[],'live','pilot import','stats.2.v'),
('area:les-3-vallees','stats','line',5,'from the operator''s base height to the top of the area; the Olympe gondola starts lower, at Brides-les-Bains','{}'::text[],'live','pilot import','stats.2.t'),
('area:les-3-vallees','stats','line',6,'{{f:F000042}}',array['F000042']::text[],'live','pilot import','stats.3.v'),
('area:les-3-vallees','stats','line',7,'for six days, adult, high season 2026/27; {{f:F000043}} in the first and last weeks',array['F000043']::text[],'live','pilot import','stats.3.t'),
('area:les-3-vallees','network','heading',0,'Three valleys on one ridge line','{}'::text[],'live','pilot import','network.h2'),
('area:les-3-vallees','network','para',0,'The lifts of the three valleys meet along the high ground between them. Courchevel and Méribel share the Saulire and the Col de la Loze; Méribel and the Belleville valley share the ridge from the Tougnète to Mont de la Chambre. Most of the area works as one network, and in the map data a skier starting from the village lifts of Courchevel 1850 reaches Val Thorens in {{f:F000180|w}} lift rides and comes back in {{f:F000186|w}}.',array['F000180','F000186']::text[],'live','pilot import','network.paras.0'),
('area:les-3-vallees','network','para',1,'The middle valley is the one that holds it together. From the lift bases of Méribel every sector except Orelle lies within three lift rides, and from Mottaret within two. A few lifts carry much of that traffic. Closing the Plattières gondola above Mottaret adds more lift rides across the area than closing any other single lift, followed by the Dou des Lanches chair above La Tania, the Côte Brune gondola from Les Menuires and the two Saulire lifts.','{}'::text[],'live','pilot import','network.paras.1'),
('area:les-3-vallees','network','para',2,'Three places hang on a single line of lifts. Brides-les-Bains reaches Méribel only by the Olympe gondola, in three sections, and no piste comes back down to it. Orelle village sits on the far side of the ridge in the Maurienne, linked by a gondola that climbs from about 900 m; skiers come down the same way. Saint-Martin-de-Belleville depends on its gondola and the Saint Martin Express chair above it.','{}'::text[],'live','pilot import','network.paras.2'),
('area:les-3-vallees','network','line',0,'{{f:F000180}} lift rides',array['F000180']::text[],'live','pilot import','network.figs.0.v'),
('area:les-3-vallees','network','line',1,'from the village lifts of Courchevel 1850 to Val Thorens, and {{f:F000186|w}} back',array['F000186']::text[],'live','pilot import','network.figs.0.t'),
('area:les-3-vallees','network','line',2,'No black run','{}'::text[],'live','pilot import','network.figs.1.v'),
('area:les-3-vallees','network','line',3,'is needed between any two sectors in the map data','{}'::text[],'live','pilot import','network.figs.1.t'),
('area:les-3-vallees','network','line',4,'{{f:F000218}} lift rides',array['F000218']::text[],'live','pilot import','network.figs.2.v'),
('area:les-3-vallees','network','line',5,'from the village of Moriond to Orelle, the longest crossing of the area','{}'::text[],'live','pilot import','network.figs.2.t'),
('area:les-3-vallees','network','line',6,'3 places','{}'::text[],'live','pilot import','network.figs.3.v'),
('area:les-3-vallees','network','line',7,'hang on one line of lifts: Brides-les-Bains, Saint-Martin and Orelle village','{}'::text[],'live','pilot import','network.figs.3.t'),
('area:les-3-vallees','network','line',8,'{{f:F000031}}',array['F000031']::text[],'live','pilot import','network.figs.4.v'),
('area:les-3-vallees','network','line',9,'the first sledge lift runs at Les Allues, below Méribel','{}'::text[],'live','pilot import','network.figs.4.t'),
('area:les-3-vallees','network','line',10,'{{f:F000032}}',array['F000032']::text[],'live','pilot import','network.figs.5.v'),
('area:les-3-vallees','network','line',11,'La Tania is born and Brides-les-Bains joins the area','{}'::text[],'live','pilot import','network.figs.5.t'),
('area:les-3-vallees','network','heading',1,'Explore the network','{}'::text[],'live','pilot import','network.mapTitle'),
('area:les-3-vallees','network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other area, then limit the runs to see what stays within reach.','{}'::text[],'live','pilot import','network.mapHelp'),
('area:les-3-vallees','network','caption',1,'Schematic, not to scale, with sectors moved apart for legibility. Built from OpenStreetMap lift and piste data (© OpenStreetMap contributors, snapshot 20 October 2026) with heights from the Copernicus 90 m elevation model. An orange link carries routes that no other link replaces when a single lift on it closes. Lift rides are the fewest needed between the lift bases of two areas. The model is being checked against the official 2026/27 piste map.','{}'::text[],'live','pilot import','network.caption'),
