('area:les-3-vallees','routes','heading',0,'Five sample days','{}'::text[],'live','pilot import','routes.h3'),
('area:les-3-vallees','routes','line',0,'Each trip is counted in lift rides out and back, from the first lift base in each area, with the easiest grade of run that makes it in the map data. The counts start lower than the base table further down, which starts in the village. Time on the pistes, in queues and on foot is not included.','{}'::text[],'live','pilot import','routes.intro'),
('area:les-3-vallees','routes','line',1,'Courchevel 1850','{}'::text[],'live','pilot import','routes.rows.0.from'),
('area:les-3-vallees','routes','line',2,'Val Thorens','{}'::text[],'live','pilot import','routes.rows.0.to'),
('area:les-3-vallees','routes','line',3,'Red','{}'::text[],'live','pilot import','routes.rows.0.grade'),
('area:les-3-vallees','routes','note',0,'On green and blue alone the way out takes five lift rides instead of three.','{}'::text[],'live','pilot import','routes.rows.0.note'),
('area:les-3-vallees','routes','line',4,'Méribel','{}'::text[],'live','pilot import','routes.rows.1.from'),
