('area:les-3-vallees','routes','line',6,'Green and blue','{}'::text[],'live','pilot import','routes.rows.1.grade'),
('area:les-3-vallees','routes','note',1,'The return is a single ride on the Funitel 3 Vallées and a long run down the Méribel side.','{}'::text[],'live','pilot import','routes.rows.1.note'),
('area:les-3-vallees','routes','line',7,'La Tania','{}'::text[],'live','pilot import','routes.rows.2.from'),
