('area:les-3-vallees','routes','note',3,'Out by the Saint Martin Express and both Saulire Express gondolas; the way back needs a red unless a fourth lift is added.','{}'::text[],'live','pilot import','routes.rows.3.note'),
('area:les-3-vallees','routes','line',13,'Brides-les-Bains','{}'::text[],'live','pilot import','routes.rows.4.from'),
